input.command:
mkdir -p src/platform && cat > Cargo.toml <<'EOF'
[package]
name = "xplat"
version = "0.1.0"
edition = "2024"
rust-version = "1.95" # `cfg_select!` is stable in std from this release
description = "Cross-platform library"
license = "MIT OR Apache-2.0"

[dependencies]

[lints.rust]
unexpected_cfgs = "warn"

[lints.clippy]
pedantic = { level = "warn", priority = -1 }
EOF
cat > .gitignore <<'EOF'
/target
EOF
cat > src/lib.rs <<'EOF'
//! Cross-platform library.
//!
//! Platform-specific code lives in [`platform`], which picks one backend at
//! compile time. Everything else should go through the API exported here and
//! stay free of `#[cfg]` attributes.

mod platform;

pub use platform::{family, path_separator};

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn family_is_known() {
        assert!(["unix", "windows", "wasm", "unknown"].contains(&family()));
    }

    #[test]
    fn separator_matches_std() {
        assert_eq!(path_separator(), std::path::MAIN_SEPARATOR);
    }
}
EOF
cat > src/platform/mod.rs <<'EOF'
//! Compile-time selection of the platform backend.
//!
//! Each backend module must export the same set of items. `cfg_select!` uses
//! the first arm that matches, so put more specific predicates first.

cfg_select! {
    windows => {
        mod windows;
        pub use windows::*;
    }
    unix => {
        mod unix;
        pub use unix::*;
    }
    target_family = "wasm" => {
        mod wasm;
        pub use wasm::*;
    }
    _ => {
        mod fallback;
        pub use fallback::*;
    }
}
EOF
cat > src/platform/unix.rs <<'EOF'
//! Unix backend (Linux, macOS, BSDs, ...).

#[must_use]
pub fn family() -> &'static str {
    "unix"
}

#[must_use]
pub fn path_separator() -> char {
    '/'
}
EOF
cat > src/platform/windows.rs <<'EOF'
//! Windows backend.

#[must_use]
pub fn family() -> &'static str {
    "windows"
}

#[must_use]
pub fn path_separator() -> char {
    '\\'
}
EOF
cat > src/platform/wasm.rs <<'EOF'
//! WebAssembly backend.

#[must_use]
pub fn family() -> &'static str {
    "wasm"
}

#[must_use]
pub fn path_separator() -> char {
    '/'
}
EOF
cat > src/platform/fallback.rs <<'EOF'
//! Fallback for targets without a dedicated backend.

#[must_use]
pub fn family() -> &'static str {
    "unknown"
}

#[must_use]
pub fn path_separator() -> char {
    '/'
}
EOF
cargo build 2>&1 | tail -3 && cargo test 2>&1 | grep -E "test result|error" ; cargo clippy --all-targets 2>&1 | tail -3; rustup target list --installed 2>/dev/null

